17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.slf4j.Logger;
24	import org.slf4j.LoggerFactory;
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.audit.OwnerAuditEvents;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
43	import org.springframework.samples.petclinic.rest.validation.EmailDomainValidator;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.server.ResponseStatusException;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    private static final Logger auditLogger = LoggerFactory.getLogger("AUDIT");
64	
65	    private static final Logger notifyLogger = LoggerFactory.getLogger("NOTIFY");
66	
67	    /** The per-city soft capacity: at or above this owner count a city is over its soft capacity. */
68	    private static final int SOFT_CAPACITY = 40;
69	
70	    /** The per-city hard limit: a create is rejected once a city already holds this many owners. */
71	    private static final int HARD_CAPACITY = 50;
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    private final OwnerAuditEvents ownerAuditEvents;
82	
83	    public OwnerRestControllerV1(ClinicService clinicService,
84	                                 OwnerMapper ownerMapper,
85	                                 PetMapper petMapper,
86	                                 VisitMapper visitMapper,
87	                                 OwnerAuditEvents ownerAuditEvents) {
88	        this.clinicService = clinicService;
89	        this.ownerMapper = ownerMapper;
90	        this.petMapper = petMapper;
91	        this.visitMapper = visitMapper;
92	        this.ownerAuditEvents = ownerAuditEvents;
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
98	        Collection<Owner> owners;
99	        if (lastName != null) {
100	            owners = this.clinicService.findOwnerByLastName(lastName);
101	        } else {
102	            owners = this.clinicService.findAllOwners();
103	        }
104	        if (owners.isEmpty()) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
113	        Owner owner = this.clinicService.findOwnerById(ownerId);
114	        if (owner == null) {
115	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
116	        }
117	        return new ResponseEntity<>(toOwnerDtoWithDerived(owner), HttpStatus.OK);
118	    }
119	
120	    /**
121	     * Builds the read representation of a persisted owner, populating the derived fields
122	     * ({@code householdSize}, {@code bulkSignupWarning}, {@code capacityWarning}) that are not
123	     * stored on the entity.
124	     */
125	    private OwnerDto toOwnerDtoWithDerived(Owner owner) {
126	        owner.setHouseholdSize(this.clinicService.countOwnersByHouseholdId(owner.getHouseholdId()));
127	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
128	        ownerDto.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
129	        ownerDto.setCapacityWarning(isApproachingCapacity(owner.getCity()));
130	        ownerDto.setRiskFlag(isRisk(owner));
131	        return ownerDto;
132	    }
133	
134	    /**
135	     * Whether the owner should be flagged for review via the read-only {@code riskFlag} field: true
136	     * when any of the following hold, otherwise false. The owner is a possible duplicate
137	     * ({@link Owner#getPossibleDuplicate()}); its email domain is disposable-adjacent
138	     * ({@link EmailDomainValidator#isDisposableAdjacent(String)}); or its city is over its soft
139	     * capacity (see {@link #isOverSoftCapacity(String)}).
140	     */
141	    private boolean isRisk(Owner owner) {
142	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
143	            || EmailDomainValidator.isDisposableAdjacent(owner.getEmail())
144	            || isOverSoftCapacity(owner.getCity());
145	    }
146	
147	    /**
148	     * Whether {@code city} is over its soft capacity: it already holds {@link #SOFT_CAPACITY} or
149	     * more owners. The soft capacity sits below the per-city hard limit enforced at create time
150	     * (see {@link #addOwner}), so this stays true from the soft capacity right up to the full city.
151	     */
152	    private boolean isOverSoftCapacity(String city) {
153	        return this.clinicService.countOwnersByCity(city) >= SOFT_CAPACITY;
154	    }
155	
156	    /**
157	     * Whether more than 80 owners have already been created on {@code registrationDate},
158	     * signalling a bulk-signup surge for the read-only {@code bulkSignupWarning} field.
159	     */
160	    private boolean isBulkSignup(LocalDate registrationDate) {
161	        return this.clinicService.countOwnersByRegistrationDate(registrationDate) > 80;
162	    }
163	
164	    /**
165	     * Whether {@code city} already holds from the soft capacity up to one below the hard limit
166	     * (40 to 49 inclusive), signalling that it is approaching the per-city capacity limit of 50,
167	     * for the read-only {@code capacityWarning} field. The hard rejection at 50 (see
168	     * {@link #addOwner}) is unaffected.
169	     */
170	    private boolean isApproachingCapacity(String city) {
171	        int count = this.clinicService.countOwnersByCity(city);
172	        return count >= SOFT_CAPACITY && count < HARD_CAPACITY;
173	    }
174	
175	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
176	    @Override
177	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
178	        // Idempotent replay: a repeat with an already-seen key returns the originally created
179	        // owner with 200 rather than creating (and possibly rejecting as) a duplicate.
180	        Integer existingId = this.clinicService.findOwnerIdByIdempotencyKey(idempotencyKey);
181	        if (existingId != null) {
182	            Owner existing = this.clinicService.findOwnerById(existingId);
183	            if (existing != null) {
184	                return new ResponseEntity<>(toOwnerDtoWithDerived(existing), HttpStatus.OK);
185	            }
186	        }
187	        HttpHeaders headers = new HttpHeaders();
188	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
189	        LocalDate registrationDate = owner.resolveRegistrationDate();
190	        if (this.clinicService.countOwnersByRegistrationDate(registrationDate) >= 100) {
191	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
192	                "The daily owner registration limit has been reached; please retry later");
193	        }
194	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= HARD_CAPACITY) {
195	            throw new ResponseStatusException(HttpStatus.CONFLICT,
196	                "The requested city has reached its owner capacity");
197	        }
198	        // The household id is deterministic: owners that share a (normalized lastName, postcode)
199	        // share it automatically. It feeds the membership-level cap and household sizing below.
200	        owner.setHouseholdId(this.clinicService.computeHouseholdId(owner));
201	        // A new owner joining an existing household (owners sharing a normalized lastName and
202	        // postcode) has its membershipLevel capped at one above the current maximum membershipLevel
203	        // among the existing household members. With no existing household member, no cap applies.
204	        owner.setMembershipLevelCap(this.clinicService.computeMembershipLevelCap(owner.getHouseholdId()));
205	        // Hard duplicate detection is consolidated into the owner's derived identity key (see
206	        // Owner#getIdentityKey): reject only when the new owner's whole key matches an existing one.
207	        // There is no separate household-duplicate 409: two owners sharing a lastName and postcode
208	        // but differing in telephone (or email) have distinct identity keys and are allowed.
209	        if (this.clinicService.existsOwnerWithIdentityKey(owner.getIdentityKey())) {
210	            throw new ResponseStatusException(HttpStatus.CONFLICT,
211	                "An owner with the same identity already exists");
212	        }
213	        // Soft-match: the identity key differs, yet the surname's soundex and the postcode match an
214	        // existing owner, flagged 'possibleDuplicate'. This is exactly the same lastName/postcode,
215	        // different telephone case that is no longer a hard duplicate.
216	        Integer possibleDuplicateOf = this.clinicService.findPossibleDuplicateOwnerId(owner);
217	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
218	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
219	        owner.setNamesakeCount(
220	            this.clinicService.countOwnersByName(owner.getFirstName(), owner.getLastName()));
221	        this.clinicService.saveOwner(owner);
222	        this.clinicService.registerIdempotencyKey(idempotencyKey, owner.getId());
223	        OwnerDto ownerDto = toOwnerDtoWithDerived(owner);
224	        auditLogger.info(
225	            "owner created: id={} memberId={} registrationDate={} membershipLevel={}",
226	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
227	            ownerDto.getMembershipLevel());
228	        // Immutable structured event (schema version 2), in addition to the human-readable line
229	        // above. It carries the owner's primary identifier (Owner#primaryIdentifier), i.e. its
230	        // version-2 memberId, and the owner segment recomputed from that version-2 identity.
231	        this.ownerAuditEvents.ownerCreated(
232	            owner.getId(), owner.primaryIdentifier(), ownerDto.getMembershipLevel(),
233	            ownerMapper.formatOwnerSegment(owner));
234	        // Enqueue a welcome notification for the freshly created owner: the NOTIFY line
235	        // carries the owner id and its memberId so downstream consumers can address it.
236	        notifyLogger.info("welcome: owner id={} memberId={}", owner.getId(), owner.getMemberId());
237	        headers.setLocation(UriComponentsBuilder.newInstance()
238	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
239	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
240	    }
241	
242	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
243	    @Override
244	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
245	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
246	        if (currentOwner == null) {
247	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
248	        }
249	        currentOwner.setAddressLine1(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine1()));
250	        currentOwner.setAddressLine2(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine2()));
251	        currentOwner.setAddress(AddressNormalizer.compose(
252	            currentOwner.getAddressLine1(), currentOwner.getAddressLine2(),
253	            ownerMapper.normalizeAddress(ownerFieldsDto.getAddress())));
254	        currentOwner.setCity(ownerFieldsDto.getCity());
255	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
256	        currentOwner.setLastName(ownerFieldsDto.getLastName());
257	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
258	        currentOwner.setEmail(ownerFieldsDto.getEmail());
259	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
260	        this.clinicService.saveOwner(currentOwner);
261	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
262	    }
263	
264	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
265	    @Transactional
266	    @Override
267	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
268	        Owner owner = this.clinicService.findOwnerById(ownerId);
269	        if (owner == null) {
270	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
271	        }
272	        this.clinicService.deleteOwner(owner);
273	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
274	    }
275	
276	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
277	    @Override
278	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
279	        Owner owner = this.clinicService.findOwnerById(ownerId);
280	        if (owner == null) {
281	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
282	        }
283	        HttpHeaders headers = new HttpHeaders();
284	        Pet pet = petMapper.toPet(petFieldsDto);
285	        owner.setId(ownerId);
286	        pet.setOwner(owner);
287	        pet.getType().setName(null);
288	        this.clinicService.savePet(pet);
289	        PetDto petDto = petMapper.toPetDto(pet);
290	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
291	            .buildAndExpand(pet.getId()).toUri());
292	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
293	    }
294	
295	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
296	    @Override
297	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
298	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
299	        if (currentOwner != null) {
300	            Pet currentPet = this.clinicService.findPetById(petId);
301	            if (currentPet != null) {
302	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
303	                currentPet.setName(petFieldsDto.getName());
304	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
305	                this.clinicService.savePet(currentPet);
306	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
307	            }
308	        }
309	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
310	    }
311	
312	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
313	    @Override
314	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
315	        HttpHeaders headers = new HttpHeaders();
316	        Visit visit = visitMapper.toVisit(visitFieldsDto);
317	        Pet pet = new Pet();
318	        pet.setId(petId);
319	        visit.setPet(pet);
320	        this.clinicService.saveVisit(visit);
321	        VisitDto visitDto = visitMapper.toVisitDto(visit);
322	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
323	            .buildAndExpand(visit.getId()).toUri());
324	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
325	    }
326	
327	
328	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
329	    @Override
330	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
331	        Owner owner = this.clinicService.findOwnerById(ownerId);
332	        if (owner != null) {
333	            Pet pet = owner.getPet(petId);
334	            if (pet != null) {
335	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
336	            }
337	        }
338	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
339	    }
340	}
