71	        if (owner == null || owner.getId() == null) {
72	            return null;
73	        }
74	        return "/api/owners/" + owner.getId();
75	    }
76	
77	    /**
78	     * Derives an owner's preferred contact channel for the read-only {@code contactPreference}
79	     * field: {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
80	     */
81	    @Named("formatContactPreference")
82	    default String formatContactPreference(Owner owner) {
83	        if (owner == null) {
84	            return null;
85	        }
86	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
87	        return hasEmail ? "EMAIL" : "PHONE";
88	    }
89	
90	    /**
91	     * Derives an owner's user-facing {@code locality}: the plain region code derived from the owner's
92	     * postcode/city (see {@link Owner#deriveRegion()}), which prefers the postcode over the city and
93	     * defaults to {@code 'UNKNOWN'}. This is the untagged region: the {@code 'V2'} version tag mixed
94	     * into the identifiers never appears here, so the locality stays a plain region such as
95	     * {@code 'NSW'}. Returns {@code 'UNKNOWN'} when the owner is absent.
