97	    @Named("formatLocality")
98	    default String formatLocality(Owner owner) {
99	        if (owner == null) {
100	            return "UNKNOWN";
101	        }
102	        return owner.deriveRegion();
103	    }
104	
105	    /**
106	     * Derives an owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}. TIER is
107	     * {@code 'PREMIUM'} when the owner's {@code membershipLevel} is 3 or more, otherwise
108	     * {@code 'STANDARD'}. AREA is {@code 'METRO'} when the owner's locality is a known region
109	     * (NSW, VIC or QLD), otherwise {@code 'REGIONAL'}. Both the membership level and the locality
110	     * are taken from {@link #formatMembershipLevel(Owner)} and {@link #formatLocality(Owner)}, so
111	     * the segment always agrees with those reported fields.
112	     */
113	    @Named("formatOwnerSegment")
114	    default String formatOwnerSegment(Owner owner) {
115	        if (owner == null) {
116	            return null;
117	        }
118	        String tier = formatMembershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
119	        String area = REGION_TIMEZONE.containsKey(formatLocality(owner)) ? "METRO" : "REGIONAL";
120	        return tier + "_" + area;
121	    }
122	
123	    /**
124	     * Fixed region-to-timezone table mapping each canonical region to its IANA timezone name.
125	     */
126	    Map<String, String> REGION_TIMEZONE = Map.of(
127	        "NSW", "Australia/Sydney",
128	        "VIC", "Australia/Melbourne",
129	        "QLD", "Australia/Brisbane");
130	
131	    /**
132	     * Derives an owner's {@code timezone} as the IANA timezone name for its locality/region, using
133	     * the fixed region-to-timezone table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
134	     * QLD-&gt;Australia/Brisbane). The region is taken from {@link #formatLocality(Owner)}, so the
135	     * timezone always agrees with the reported locality. Returns {@code null} when the region is not
