154	            return null;
155	        }
156	        return owner.membershipPoints(owner.getHouseholdSize());
157	    }
158	
159	    /**
160	     * Derives an owner's numeric membership level for the read-only {@code membershipLevel} field,
161	     * using the household size resolved onto the owner at read time. Delegates to
162	     * {@link Owner#membershipLevel(Integer)}, which maps points to a level and applies the owner's
163	     * membership-level cap.
164	     */
165	    @Named("formatMembershipLevel")
166	    default Integer formatMembershipLevel(Owner owner) {
167	        if (owner == null) {
168	            return null;
169	        }
170	        return owner.membershipLevel(owner.getHouseholdSize());
171	    }
172	
173	    /**
174	     * Formats an owner's fiscal year as {@code 'FY<YY>'}, where YY is the last two digits of the
175	     * fiscal year derived from the business-day-adjusted registration date (e.g. {@code 'FY27'}),
176	     * for the read-only {@code fiscalYear} field. Each fiscal year starts on 1 July and is named by
177	     * the calendar year in which it ends. Null when the registration date is absent.
178	     */
179	    @Named("formatFiscalYear")
180	    default String formatFiscalYear(Owner owner) {
181	        if (owner == null || owner.getRegistrationDate() == null) {
182	            return null;
183	        }
184	        return String.format("FY%02d", Owner.fiscalYear(owner.getRegistrationDate()) % 100);
185	    }
186	
187	    /**
188	     * Formats an owner's stored names as {@code 'LastName, FirstName'} for the read-only
189	     * {@code displayName} field.
190	     */
191	    @Named("formatDisplayName")
192	    default String formatDisplayName(Owner owner) {
193	        return owner == null ? null : owner.getLastName() + ", " + owner.getFirstName();
194	    }
195	
196	    /**
197	     * Formats an owner's initials as the upper-cased first letters of firstName and
198	     * lastName, dot-separated with a trailing dot (e.g. {@code 'J.S.'}), for the
199	     * read-only {@code initials} field.
200	     */
201	    @Named("formatInitials")
202	    default String formatInitials(Owner owner) {
203	        return owner == null ? null
204	            : Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
205	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
206	    }
207	
208	    /**
209	     * Formats the owner's stored E.164 telephone for human display as the country code, a space
210	     * and the national digits grouped in threes (e.g. {@code '+61412345678'} becomes
211	     * {@code '+61 412 345 678'}), for the read-only {@code telephoneDisplay} field. The raw
212	     * {@code telephone} field stays in E.164 form. Null when no telephone is present.
213	     */
214	    @Named("formatTelephoneDisplay")
215	    default String formatTelephoneDisplay(Owner owner) {
216	        return owner == null ? null : TelephoneNormalizer.toDisplay(owner.getTelephone());
217	    }
218	
219	    Owner toOwner(OwnerDto ownerDto);
220	
221	    @Mapping(target = "id", ignore = true)
222	    @Mapping(target = "pets", ignore = true)
223	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
224	    @Mapping(target = "addressLine1", source = "addressLine1", qualifiedByName = "normalizeAddress")
225	    @Mapping(target = "addressLine2", source = "addressLine2", qualifiedByName = "normalizeAddress")
226	    @Mapping(target = "address", ignore = true)
227	    Owner toOwner(OwnerFieldsDto ownerDto);
228	
229	    /**
230	     * Resolves the owner's stored {@code address} after the field mapping runs, from the already
231	     * normalized {@code addressLine1}/{@code addressLine2} fields set on the target (preferred when
232	     * present) with the normalized flat {@code address} as the fallback. See
233	     * {@link AddressNormalizer#compose(String, String, String)} for the composition rule.
234	     */
235	    @AfterMapping
236	    default void composeAddress(OwnerFieldsDto ownerDto, @MappingTarget Owner owner) {
237	        owner.setAddress(AddressNormalizer.compose(
238	            owner.getAddressLine1(), owner.getAddressLine2(), normalizeAddress(ownerDto.getAddress())));
239	    }
240	
241	    /**
242	     * Normalizes a postal address for persistence: whitespace is trimmed and collapsed, the
243	     * text is upper-cased and common street-type abbreviations are expanded (e.g.
244	     * {@code '  12  main  st '} becomes {@code '12 MAIN STREET'}). The required-field rule is
245	     * enforced separately; an address blank after normalization is rejected.
246	     */
247	    @Named("normalizeAddress")
248	    default String normalizeAddress(String address) {
249	        return AddressNormalizer.normalize(address);
250	    }
251	
252	    /**
253	     * Normalizes a telephone number for persistence into canonical E.164 form (e.g.
254	     * {@code '0412 345 678'} becomes {@code '+61412345678'}). The formability rule is
255	     * enforced separately by {@code TelephoneValidation}.
256	     */
257	    @Named("normalizeTelephone")
258	    default String normalizeTelephone(String telephone) {
259	        return TelephoneNormalizer.toE164(telephone);
260	    }
261	
262	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
263	
264	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
265	
266	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
267	        OwnerPageDto ownerPageDto = new OwnerPageDto();
268	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
269	        ownerPageDto.setPage(ownerPage.getNumber());
270	        ownerPageDto.setSize(ownerPage.getSize());
271	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
272	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
273	        return ownerPageDto;
274	    }
275	}
