30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    /**
42	     * The fixed list of public holidays that a registration date must roll forward past, in addition
43	     * to weekends.
44	     */
45	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
46	        LocalDate.of(2026, 1, 1),
47	        LocalDate.of(2026, 1, 26),
48	        LocalDate.of(2026, 4, 25),
49	        LocalDate.of(2026, 12, 25),
50	        LocalDate.of(2026, 12, 28));
51	
52	    /**
53	     * The fixed version tag mixed into the version-2 identity derivations. It is folded into the
54	     * region code used inside every owner identifier (the {@link #getMemberId() memberId}, the
55	     * {@link #getHouseholdId() householdId} and the {@link #getIdentityKey() identityKey}) so each
56	     * value differs from its version-1 form. The tag is confined to the identifiers: it never leaks
57	     * into the user-facing region ({@link #deriveRegion()}) reported as locality, timezone or the
58	     * owner segment's derived region.
59	     */
60	    public static final String IDENTITY_VERSION = "V2";
61	
62	    /** Fixed city-to-region table used to derive an owner's plain region code. */
63	    private static final Map<String, String> CITY_REGION = Map.of(
64	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
65	
66	    /** Region to inclusive 4-digit postcode range {low, high}, preferred over the city table
67	     *  when deriving an owner's region. */
68	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
69	        "NSW", new int[] {2000, 2099},
70	        "VIC", new int[] {3000, 3099},
71	        "QLD", new int[] {4000, 4099});
72	
73	    @Column(name = "title")
74	    private String title;
75	
76	    @Column(name = "address")
77	    @NotEmpty
78	    private String address;
79	
80	    @Column(name = "address_line1")
81	    private String addressLine1;
82	
83	    @Column(name = "address_line2")
84	    private String addressLine2;
85	
86	    @Column(name = "city")
87	    @NotEmpty
88	    private String city;
89	
90	    @Column(name = "telephone")
91	    @NotEmpty
92	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ followed by 8 to 15 digits)")
93	    private String telephone;
94	
95	    @Column(name = "email")
96	    private String email;
97	
98	    @Column(name = "postcode")
99	    private String postcode;
100	
101	    @Column(name = "registration_date", columnDefinition = "DATE")
102	    private LocalDate registrationDate;
103	
104	    @Column(name = "birth_date", columnDefinition = "DATE")
105	    private LocalDate birthDate;
106	
107	    @Column(name = "member_id")
108	    private String memberId;
109	
110	    @Column(name = "household_id")
111	    private String householdId;
112	
113	    @Column(name = "namesake_count")
114	    private Integer namesakeCount;
115	
116	    @Column(name = "possible_duplicate")
117	    private Boolean possibleDuplicate;
118	
119	    @Column(name = "possible_duplicate_of")
120	    private Integer possibleDuplicateOf;
121	
122	    @Column(name = "membership_level_cap")
123	    private Integer membershipLevelCap;
124	
125	    @Column(name = "deleted")
126	    private boolean deleted;
127	
128	    @Transient
129	    private Integer householdSize;
130	
131	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
132	    private Set<Pet> pets;
133	
134	    public String getTitle() {
135	        return this.title;
136	    }
137	
138	    public void setTitle(String title) {
139	        this.title = title;
140	    }
141	
142	    /**
143	     * Derives the owner's salutation for the read-only {@code salutation} field: the title, a single
144	     * space and the lastName when a title is present (e.g. {@code 'DR Who'}), or just the lastName
145	     * when no title was supplied.
146	     */
147	    @Transient
148	    public String getSalutation() {
149	        if (this.title == null || this.title.isBlank()) {
150	            return getLastName();
151	        }
152	        return this.title + " " + getLastName();
153	    }
154	
155	    public String getAddress() {
156	        return this.address;
157	    }
158	
159	    public void setAddress(String address) {
160	        this.address = address;
161	    }
162	
163	    public String getAddressLine1() {
164	        return this.addressLine1;
165	    }
166	
167	    public void setAddressLine1(String addressLine1) {
168	        this.addressLine1 = addressLine1;
169	    }
170	
171	    public String getAddressLine2() {
172	        return this.addressLine2;
173	    }
174	
175	    public void setAddressLine2(String addressLine2) {
176	        this.addressLine2 = addressLine2;
177	    }
178	
179	    public String getCity() {
180	        return this.city;
181	    }
182	
183	    public void setCity(String city) {
184	        this.city = city;
185	    }
186	
187	    public String getTelephone() {
188	        return this.telephone;
189	    }
190	
191	    public void setTelephone(String telephone) {
192	        this.telephone = telephone;
193	    }
194	
195	    public String getEmail() {
196	        return this.email;
197	    }
198	
199	    public void setEmail(String email) {
200	        this.email = email == null ? null : email.toLowerCase();
201	    }
202	
203	    public String getPostcode() {
204	        return this.postcode;
205	    }
206	
207	    public void setPostcode(String postcode) {
208	        this.postcode = postcode;
209	    }
210	
211	    public LocalDate getRegistrationDate() {
212	        return this.registrationDate;
213	    }
214	
215	    public void setRegistrationDate(LocalDate registrationDate) {
216	        this.registrationDate = registrationDate;
217	    }
218	
219	    public LocalDate getBirthDate() {
220	        return this.birthDate;
221	    }
222	
223	    public void setBirthDate(LocalDate birthDate) {
224	        this.birthDate = birthDate;
225	    }
226	
227	    /**
228	     * Derives the owner's age band from the birth date, measured against the registration date:
229	     * {@code 'MINOR'} when under 18, {@code 'ADULT'} for 18 to 64 inclusive, and {@code 'SENIOR'}
230	     * from 65 on. Returns {@code null} when either the birth date or the registration date is absent,
231	     * so an owner created without a birth date has no age band.
232	     */
233	    @Transient
234	    public String getAgeBand() {
235	        if (this.birthDate == null || this.registrationDate == null) {
236	            return null;
237	        }
238	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
239	        if (age < 18) {
240	            return "MINOR";
241	        }
242	        return age < 65 ? "ADULT" : "SENIOR";
243	    }
244	
245	    public String getMemberId() {
246	        return this.memberId;
247	    }
248	
249	    public void setMemberId(String memberId) {
250	        this.memberId = memberId;
251	    }
252	
253	    /**
254	     * This owner's primary identifier: its unified {@code memberId}. Callers that need "whatever
255	     * identifies the owner right now" (e.g. the structured audit event) read it here.
256	     */
257	    public String primaryIdentifier() {
258	        return this.memberId;
259	    }
260	
261	    public String getHouseholdId() {
262	        return this.householdId;
263	    }
264	
265	    public void setHouseholdId(String householdId) {
266	        this.householdId = householdId;
267	    }
268	
269	    public Integer getNamesakeCount() {
270	        return this.namesakeCount;
271	    }
272	
273	    public void setNamesakeCount(Integer namesakeCount) {
274	        this.namesakeCount = namesakeCount;
275	    }
276	
277	    /**
278	     * The number of owners belonging to this owner's household (owners sharing this owner's
279	     * household id, including this owner). Not persisted: it is a live count populated at read
280	     * time and feeds the {@code membershipPoints} calculation. Null when it has not been resolved.
281	     */
282	    public Integer getHouseholdSize() {
283	        return this.householdSize;
284	    }
285	
286	    public void setHouseholdSize(Integer householdSize) {
287	        this.householdSize = householdSize;
288	    }
289	
290	    /**
291	     * Whether this owner was flagged a possible (soft-match) duplicate at creation: it was not a
292	     * hard duplicate, yet it shared an existing owner's lastName and postcode while carrying a
293	     * different telephone. False when no such match existed.
294	     */
295	    public Boolean getPossibleDuplicate() {
296	        return this.possibleDuplicate;
297	    }
298	
299	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
300	        this.possibleDuplicate = possibleDuplicate;
301	    }
302	
303	    /**
304	     * The id of the existing owner this owner soft-matches (same lastName and postcode, different
305	     * telephone), or {@code null} when it is not a possible duplicate.
306	     */
307	    public Integer getPossibleDuplicateOf() {
308	        return this.possibleDuplicateOf;
309	    }
310	
311	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
312	        this.possibleDuplicateOf = possibleDuplicateOf;
313	    }
314	
315	    /**
316	     * The ceiling applied to this owner's derived {@code membershipLevel}, fixed when the owner was
317	     * created: one above the maximum membershipLevel among the household members that already existed
318	     * at that time. The reported membership level is never allowed to exceed this cap. {@code null}
319	     * when the owner had no existing household member at creation, in which case no cap applies.
320	     */
321	    public Integer getMembershipLevelCap() {
322	        return this.membershipLevelCap;
323	    }
324	
325	    public void setMembershipLevelCap(Integer membershipLevelCap) {
326	        this.membershipLevelCap = membershipLevelCap;
327	    }
328	
329	    /**
330	     * Computes this owner's membership points for the given household size. Points start at 0 and
331	     * accumulate: 2 when an email address is present, 1 when the owner had no namesakes at creation
332	     * (namesakeCount is 0), 2 for a household of 3 or more members, and 3 for tenure of one or more
333	     * elapsed fiscal years (the number of 1-July fiscal-year boundaries between the registration date
334	     * and the current date). The household size is supplied by the caller (it is a live, non-persisted
335	     * count), so a {@code null} size contributes no household points.
336	     */
337	    public int membershipPoints(Integer householdSize) {
338	        int points = 0;
339	        if (this.email != null && !this.email.isBlank()) {
340	            points += 2;
341	        }
342	        if (this.namesakeCount != null && this.namesakeCount == 0) {
343	            points += 1;
344	        }
345	        if (householdSize != null && householdSize >= 3) {
346	            points += 2;
347	        }
348	        if (this.registrationDate != null
349	            && fiscalYear(LocalDate.now()) - fiscalYear(this.registrationDate) >= 1) {
350	            points += 3;
351	        }
352	        return points;
353	    }
354	
355	    /**
356	     * Derives this owner's numeric membership level for the given household size from its membership
357	     * points: 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points. The
358	     * result is then capped at {@link #getMembershipLevelCap()} (the ceiling fixed at creation from
359	     * the household this owner joined): when a cap is present the level can never exceed it. No cap is
360	     * applied when the owner had no existing household member at creation.
361	     */
362	    public int membershipLevel(Integer householdSize) {
363	        int points = membershipPoints(householdSize);
364	        int level;
365	        if (points <= 1) {
366	            level = 1;
367	        }
368	        else if (points <= 3) {
369	            level = 2;
370	        }
371	        else if (points <= 5) {
372	            level = 3;
373	        }
374	        else {
375	            level = 4;
376	        }
377	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
378	            level = this.membershipLevelCap;
379	        }
380	        return level;
381	    }
382	
383	    /**
384	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; a
385	     * {@code DELETE /api/owners/{id}} flags it deleted while retaining the row. Deleted owners are
386	     * ignored by the create endpoint's duplicate and identity checks.
387	     */
388	    public boolean isDeleted() {
389	        return this.deleted;
390	    }
391	
392	    public void setDeleted(boolean deleted) {
393	        this.deleted = deleted;
394	    }
395	
396	    /**
397	     * Derives the owner's plain region code, preferring the postcode: the region whose inclusive
398	     * 4-digit range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) contains the postcode is used
399	     * first. When the postcode is absent or in no known range, it falls back to the fixed
400	     * city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), returning
401	     * {@code 'UNKNOWN'} when the city is not in the table. This is the user-facing region reported
402	     * as {@code locality}/{@code timezone} and used by the owner segment; the fixed
403	     * {@code 'V2'} version tag is never mixed in here.
404	     */
405	    public String deriveRegion() {
406	        if (this.postcode != null && this.postcode.matches("^[0-9]{4}$")) {
407	            int value = Integer.parseInt(this.postcode);
408	            for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
409	                int[] range = entry.getValue();
410	                if (value >= range[0] && value <= range[1]) {
411	                    return entry.getKey();
412	                }
413	            }
414	        }
415	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
416	    }
417	
418	    /**
419	     * Derives the version-2 region code used INSIDE the owner's identifiers: the plain
420	     * {@link #deriveRegion() region} with the fixed {@link #IDENTITY_VERSION 'V2'} version tag mixed
421	     * in (e.g. {@code 'NSWV2'}). This is the shared source of the version bump across the memberId,
422	     * householdId and identityKey, so every identifier differs from its version-1 form while the
423	     * plain region reported to users stays untagged.
424	     */
425	    public String deriveIdentityRegion() {
426	        return deriveRegion() + IDENTITY_VERSION;
427	    }
428	
429	    /**
430	     * The owner's derived identity key, used as the single basis for duplicate detection: the
431	     * lower-case hex SHA-256 digest over {@code identityRegion + '|' + normalizedTelephone + '|' +
432	     * lowerEmail + '|' + soundex(lastName)}, where {@code identityRegion} is the version-2 region
433	     * ({@link #deriveIdentityRegion()}, which mixes in the fixed {@code 'V2'} tag) and the telephone
434	     * and email components are empty when absent. Two owners are duplicates only when their whole
435	     * identity keys are equal, so any single differing component yields distinct keys and is allowed.
436	     * Derived from persisted fields, so it is not itself a persistent column.
437	     */
438	    @Transient
439	    public String getIdentityKey() {
440	        String normalizedTelephone = this.telephone == null ? "" : this.telephone;
441	        String lowerEmail = this.email == null ? "" : this.email.toLowerCase();
442	        String seed = deriveIdentityRegion() + "|" + normalizedTelephone + "|" + lowerEmail
443	            + "|" + soundex(getLastName());
444	        return HashUtils.sha256Hex(seed);
445	    }
446	
447	    /**
448	     * Computes the American Soundex code for a name: the retained first letter followed by three
449	     * digits derived from the remaining consonants (b,f,p,v-&gt;1; c,g,j,k,q,s,x,z-&gt;2; d,t-&gt;3;
450	     * l-&gt;4; m,n-&gt;5; r-&gt;6), with adjacent equal codes collapsed, h and w ignored (so they do
451	     * not separate equal codes) and vowels acting as separators, right-padded with zeros to length
452	     * four. Returns an empty string when the value is null or holds no letters, so surnames that
453	     * sound alike share a code.
454	     */
455	    public static String soundex(String value) {
456	        if (value == null) {
457	            return "";
458	        }
459	        String letters = value.toUpperCase().replaceAll("[^A-Z]", "");
460	        if (letters.isEmpty()) {
461	            return "";
462	        }
463	        StringBuilder code = new StringBuilder();
464	        code.append(letters.charAt(0));
465	        char previous = soundexDigit(letters.charAt(0));
466	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
467	            char c = letters.charAt(i);
468	            if (c == 'H' || c == 'W') {
469	                continue;
470	            }
471	            char digit = soundexDigit(c);
472	            if (digit != '0' && digit != previous) {
473	                code.append(digit);
474	            }
475	            previous = digit;
476	        }
477	        while (code.length() < 4) {
478	            code.append('0');
479	        }
480	        return code.toString();
481	    }
482	
483	    /** Maps a letter to its Soundex digit, or {@code '0'} for vowels, y, h and w. */
484	    private static char soundexDigit(char c) {
485	        return switch (c) {
486	            case 'B', 'F', 'P', 'V' -> '1';
487	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
488	            case 'D', 'T' -> '3';
489	            case 'L' -> '4';
490	            case 'M', 'N' -> '5';
491	            case 'R' -> '6';
492	            default -> '0';
493	        };
494	    }
495	
496	    /**
497	     * Establishes the effective registration date at persist time, so the create-time default
498	     * applies to any persistence path.
499	     */
500	    @PrePersist
501	    protected void defaultRegistrationDate() {
502	        resolveRegistrationDate();
503	    }
504	
505	    /**
506	     * Resolves this owner's effective registration date and stores it: the supplied value is used, or
507	     * the server's current date when none was supplied, and the result is rolled forward onto a
508	     * business day (a Saturday, Sunday or public holiday rolls forward to the next business day).
509	     * Returns the resolved date.
510	     * Idempotent, so it is safe to call from both the create flow and the persist hook.
511	     */
512	    public LocalDate resolveRegistrationDate() {
513	        LocalDate effective = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
514	        this.registrationDate = toBusinessDay(effective);
515	        return this.registrationDate;
516	    }
517	
518	    /**
519	     * Derives the fiscal year that a date falls in, where each fiscal year starts on 1 July and is
520	     * identified by the calendar year in which it ends: a date from July onwards belongs to the
521	     * fiscal year ending in the following calendar year (e.g. 2 July 2026 gives 2027), while a date
522	     * from January to June belongs to the fiscal year ending in its own calendar year. Returns
523	     * {@code null} when the date is absent.
524	     */
525	    public static Integer fiscalYear(LocalDate date) {
526	        if (date == null) {
527	            return null;
528	        }
529	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
530	    }
531	
532	    /**
533	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
534	     * holiday is advanced to the next non-holiday weekday, while any other weekday (and {@code null})
535	     * is returned unchanged. Applying this to a date that is already a business day is a no-op, so it
536	     * is safe to call more than once.
537	     */
538	    public static LocalDate toBusinessDay(LocalDate date) {
539	        if (date == null) {
540	            return null;
541	        }
542	        LocalDate result = date;
543	        while (isWeekend(result) || PUBLIC_HOLIDAYS.contains(result)) {
544	            result = result.plusDays(1);
545	        }
546	        return result;
547	    }
548	
549	    private static boolean isWeekend(LocalDate date) {
550	        return switch (date.getDayOfWeek()) {
551	            case SATURDAY, SUNDAY -> true;
552	            default -> false;
553	        };
554	    }
555	
556	    protected Set<Pet> getPetsInternal() {
557	        if (this.pets == null) {
558	            this.pets = new HashSet<>();
559	        }
560	        return this.pets;
561	    }
562	
563	    protected void setPetsInternal(Set<Pet> pets) {
564	        this.pets = pets;
565	    }
566	
567	    public List<Pet> getPets() {
568	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
569	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
570	        return Collections.unmodifiableList(sortedPets);
571	    }
572	
573	    public void setPets(List<Pet> pets) {
574	        this.pets = new HashSet<>(pets);
575	    }
576	
577	    public void addPet(Pet pet) {
578	        getPetsInternal().add(pet);
579	        pet.setOwner(this);
580	    }
581	
582	    /**
583	     * Return the Pet with the given name, or null if none found for this Owner.
584	     *
585	     * @param name to test
586	     * @return true if pet name is already in use
587	     */
588	    public Pet getPet(String name) {
589	        return getPet(name, false);
590	    }
591	
592	    /**
593	     * Return the Pet with the given name, or null if none found for this Owner.
594	     *
595	     * @param name to test
596	     * @return true if pet name is already in use
597	     */
598	    public Pet getPet(String name, boolean ignoreNew) {
599	        name = name.toLowerCase();
600	        for (Pet pet : getPetsInternal()) {
601	            if (!ignoreNew || !pet.isNew()) {
602	                String compName = pet.getName();
603	                compName = compName.toLowerCase();
604	                if (compName.equals(name)) {
605	                    return pet;
606	                }
607	            }
608	        }
609	        return null;
610	    }
611	
612	    public Pet getPet(Integer petId) {
613	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
614	    }
615	
616	    @Override
617	    public String toString() {
618	        return new ToStringCreator(this)
619	
620	            .append("id", this.getId())
621	            .append("new", this.isNew())
622	            .append("lastName", this.getLastName())
623	            .append("firstName", this.getFirstName())
624	            .append("address", this.address)
625	            .append("city", this.city)
626	            .append("telephone", this.telephone)
627	            .toString();
628	    }
629	}
