246	    @Override
247	    @Transactional
248	    public void saveOwner(Owner owner) throws DataAccessException {
249	        if (owner.getMemberId() == null) {
250	            owner.setMemberId(generateMemberId(owner));
251	        }
252	        ownerRepository.save(owner);
253	
254	    }
255	
256	    /**
257	     * Builds an owner's unified member id formatted {@code '<REGION><FY><HASH8><CHK>'}, where REGION
258	     * is the version-2 region code derived from the owner's postcode/city (the plain region with the
259	     * fixed {@code 'V2'} version tag mixed in, see {@link Owner#deriveIdentityRegion()}), FY is the
260	     * two-digit fiscal year of the owner's business-day-adjusted registration date, HASH8 is the
261	     * first 8 upper-case hex characters of the SHA-256 digest over the owner's normalized telephone
262	     * concatenated with its last name, and CHK is a single Luhn check digit computed over the digits
263	     * of {@code <REGION><FY><HASH8>} (e.g. {@code 'NSWV2271A2B3C4D5'}).
264	     *
265	     * <p>When the computed member id collides with an existing owner's {@code memberId}, {@code '-<n>'}
266	     * is appended with the smallest {@code n} of 2 or more that makes it unique, so distinct owners
267	     * always receive distinct member ids.
268	     */
269	    private String generateMemberId(Owner owner) {
270	        String region = owner.deriveIdentityRegion();
271	        String fy = String.format("%02d", Owner.fiscalYear(owner.resolveRegistrationDate()) % 100);
272	        String core = region + fy + hash8(owner);
273	        String base = core + luhnCheckDigit(core);
274	        Set<String> existing = ownerRepository.findAll().stream()
275	            .map(Owner::getMemberId)
276	            .filter(Objects::nonNull)
277	            .collect(Collectors.toSet());
278	        if (!existing.contains(base)) {
279	            return base;
280	        }
281	        for (int n = 2; ; n++) {
282	            String candidate = base + "-" + n;
283	            if (!existing.contains(candidate)) {
284	                return candidate;
285	            }
286	        }
287	    }
288	
289	    /**
290	     * Computes the Luhn check digit (0-9) over the decimal digits contained in {@code value},
291	     * ignoring any non-digit characters. Used to derive the CHK segment of an owner's member id.
292	     */
293	    private static int luhnCheckDigit(String value) {
294	        int sum = 0;
295	        boolean dbl = true;
296	        for (int i = value.length() - 1; i >= 0; i--) {
297	            char c = value.charAt(i);
298	            if (c < '0' || c > '9') {
299	                continue;
300	            }
301	            int d = c - '0';
302	            if (dbl) {
303	                d *= 2;
304	                if (d > 9) {
305	                    d -= 9;
306	                }
307	            }
308	            sum += d;
309	            dbl = !dbl;
310	        }
311	        return (10 - (sum % 10)) % 10;
312	    }
313	
314	    /**
315	     * Computes an owner's identity hash as the first 8 upper-case hex characters of the SHA-256
316	     * digest over its normalized telephone concatenated with its last name.
317	     */
318	    private static String hash8(Owner owner) {
319	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
320	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
321	        return HashUtils.sha256UpperHex(telephone + lastName, 8);
322	    }
323	
324	    /**
325	     * Whether any existing owner has the given derived identity key. This is the single basis for
326	     * duplicate detection: a create is rejected only when the whole key matches an existing owner
327	     * exactly. See {@link Owner#getIdentityKey()} for the key's definition.
328	     */
329	    @Override
330	    @Transactional(readOnly = true)
331	    public boolean existsOwnerWithIdentityKey(String identityKey) throws DataAccessException {
332	        if (identityKey == null) {
333	            return false;
334	        }
335	        return ownerRepository.findAll().stream()
336	            .filter(existing -> !existing.isDeleted())
337	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
338	    }
339	
340	    /**
341	     * Finds the id of an existing owner that {@code owner} soft-matches (a possible duplicate): one
342	     * whose surname shares this owner's {@code soundex(lastName)} and whose postcode matches, yet
343	     * whose identity key differs (so it is not itself a hard duplicate). This is a weaker match than
344	     * the hard-duplicate identity key, so it is only meaningful for an owner that is not itself a hard
345	     * duplicate; in particular two owners with the same lastName and postcode but different telephones
346	     * are soft matches rather than hard duplicates. When several owners match, the one with the lowest
347	     * id is returned; {@code null} is returned when there is no match (or lastName/postcode is absent),
348	     * meaning the owner is not a possible duplicate.
349	     */
350	    @Override
351	    @Transactional(readOnly = true)
352	    public Integer findPossibleDuplicateOwnerId(Owner owner) throws DataAccessException {
353	        if (owner == null || owner.getLastName() == null || owner.getPostcode() == null) {
354	            return null;
355	        }
356	        String soundex = Owner.soundex(owner.getLastName());
357	        String postcode = owner.getPostcode();
358	        String identityKey = owner.getIdentityKey();
359	        return ownerRepository.findAll().stream()
360	            .filter(existing -> !existing.isDeleted())
361	            .filter(existing -> soundex.equals(Owner.soundex(existing.getLastName()))
362	                && postcode.equals(existing.getPostcode())
363	                && !Objects.equals(identityKey, existing.getIdentityKey()))
364	            .map(Owner::getId)
365	            .filter(Objects::nonNull)
366	            .min(Comparator.naturalOrder())
367	            .orElse(null);
368	    }
369	
370	    /**
371	     * Counts the existing owners whose firstName and lastName match the given values
372	     * case-insensitively. Used to record an owner's namesake count at creation time.
373	     */
374	    @Override
375	    @Transactional(readOnly = true)
376	    public int countOwnersByName(String firstName, String lastName) throws DataAccessException {
377	        if (firstName == null || lastName == null) {
378	            return 0;
379	        }
380	        return (int) ownerRepository.findAll().stream()
381	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
382	                && lastName.equalsIgnoreCase(existing.getLastName()))
383	            .count();
384	    }
385	
386	    /**
387	     * Counts the existing owners whose city matches the given value case-insensitively.
388	     * Used to enforce the per-city capacity rule at creation time.
389	     */
390	    @Override
391	    @Transactional(readOnly = true)
392	    public int countOwnersByCity(String city) throws DataAccessException {
393	        if (city == null) {
394	            return 0;
395	        }
396	        return (int) ownerRepository.findAll().stream()
397	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
398	            .count();
399	    }
400	
401	    /**
402	     * Counts the existing owners whose registration date matches the given value.
403	     * Used to enforce the per-day owner creation limit.
404	     */
405	    @Override
406	    @Transactional(readOnly = true)
407	    public int countOwnersByRegistrationDate(LocalDate registrationDate) throws DataAccessException {
408	        if (registrationDate == null) {
409	            return 0;
410	        }
411	        return (int) ownerRepository.findAll().stream()
412	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
413	            .count();
414	    }
415	
416	    /**
417	     * Computes an owner's deterministic household id: the first 12 upper-case hex characters of the
418	     * SHA-256 digest over the version-2 region code ({@link Owner#deriveIdentityRegion()}, which
419	     * mixes in the fixed {@code 'V2'} version tag), a {@code '|'} separator, the owner's normalized
420	     * last name, a {@code '|'} separator and its postcode
421	     * ({@code identityRegion + '|' + normalizedLastName + '|' + postcode}). Owners that share a last
422	     * name and postcode therefore map to the same household id automatically, without any explicit
423	     * linking. Returns {@code null} when the last name or postcode is absent or blank, since no
424	     * household can be formed without both.
425	     */
426	    @Override
427	    @Transactional(readOnly = true)
428	    public String computeHouseholdId(Owner owner) throws DataAccessException {
429	        if (owner == null) {
430	            return null;
431	        }
432	        String normalizedLastName = normalizeHouseholdField(owner.getLastName());
433	        String postcode = owner.getPostcode();
434	        if (normalizedLastName == null || normalizedLastName.isBlank()
435	            || postcode == null || postcode.isBlank()) {
436	            return null;
437	        }
438	        return HashUtils.sha256UpperHex(
439	            owner.deriveIdentityRegion() + "|" + normalizedLastName + "|" + postcode, 12);
440	    }
441	
442	    /**
443	     * Counts the owners that belong to the household identified by the given (deterministic)
444	     * household id, i.e. the number of owners currently sharing it. Used to size a household for
445	     * the membership-points calculation. Returns {@code 0} when the id is absent.
446	     */
447	    @Override
448	    @Transactional(readOnly = true)
449	    public int countOwnersByHouseholdId(String householdId) throws DataAccessException {
450	        if (householdId == null || householdId.isBlank()) {
451	            return 0;
452	        }
453	        return (int) ownerRepository.findAll().stream()
454	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
455	            .count();
456	    }
457	
458	    /**
459	     * Returns the existing, non-deleted owners that belong to the household identified by the given
460	     * (deterministic) household id, i.e. the current members of that household. Used to derive the
461	     * membership-level ceiling a new owner joining the household is subject to. Returns an empty
462	     * collection when the id is absent.
463	     */
464	    @Override
465	    @Transactional(readOnly = true)
466	    public Collection<Owner> findOwnersByHouseholdId(String householdId) throws DataAccessException {
467	        if (householdId == null || householdId.isBlank()) {
468	            return List.of();
469	        }
470	        return ownerRepository.findAll().stream()
471	            .filter(existing -> !existing.isDeleted())
472	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
473	            .toList();
474	    }
475	
476	    /**
477	     * Computes the membership-level ceiling for a new owner joining the household identified by the
478	     * given (deterministic) household id: one above the current maximum membershipLevel among the
479	     * existing (non-deleted) household members. The members' live household size is passed explicitly
480	     * to {@link Owner#membershipLevel(Integer)}, so no persistent state is mutated. Returns
481	     * {@code null} when the household has no existing member, so no cap applies to the new owner.
482	     */
483	    @Override
484	    @Transactional(readOnly = true)
485	    public Integer computeMembershipLevelCap(String householdId) throws DataAccessException {
486	        Collection<Owner> members = findOwnersByHouseholdId(householdId);
487	        if (members.isEmpty()) {
488	            return null;
489	        }
490	        int maxLevel = 0;
491	        for (Owner member : members) {
492	            int level = member.membershipLevel(members.size());
493	            if (level > maxLevel) {
494	                maxLevel = level;
495	            }
496	        }
497	        return maxLevel + 1;
498	    }
499	
500	    /**
501	     * Normalizes a household-identity field for comparison by trimming, collapsing internal
502	     * runs of whitespace to a single space and lower-casing, so values that differ only in
503	     * whitespace or letter case are treated as equal.
504	     */
505	    private static String normalizeHouseholdField(String value) {
506	        if (value == null) {
507	            return null;
508	        }
509	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
510	    }
511	
512	    @Override
513	    @Transactional(readOnly = true)
514	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
515	        return ownerRepository.findByLastName(lastName);
516	    }
517	
518	    /**
519	     * Returns the id of the owner previously created for the given idempotency key, or {@code null}
520	     * when the key has not been seen (or is absent), meaning the create should proceed normally.
521	     */
522	    @Override
523	    public Integer findOwnerIdByIdempotencyKey(String idempotencyKey) throws DataAccessException {
524	        if (idempotencyKey == null || idempotencyKey.isBlank()) {
525	            return null;
526	        }
527	        return idempotencyKeys.get(idempotencyKey);
528	    }
529	
530	    /**
531	     * Records that the given idempotency key produced the owner with the given id, so a later create
532	     * repeating the key replays that owner instead of duplicating it. No-op when the key is absent.
533	     */
534	    @Override
535	    public void registerIdempotencyKey(String idempotencyKey, Integer ownerId) throws DataAccessException {
536	        if (idempotencyKey == null || idempotencyKey.isBlank() || ownerId == null) {
537	            return;
538	        }
539	        idempotencyKeys.put(idempotencyKey, ownerId);
540	    }
541	
